import type { TranslationKey } from "../translations";
import type { VelairPanelView } from "../types";

export type PanelTabDefinition = {
  icon: string;
  labelKey: TranslationKey;
  view: VelairPanelView;
};

export const PANEL_TABS: PanelTabDefinition[] = [
  {
    icon: "mdi:view-dashboard-outline",
    labelKey: "overview",
    view: "overview",
  },
  {
    icon: "mdi:calendar-clock",
    labelKey: "schedules",
    view: "schedules",
  },
  {
    icon: "mdi:format-list-bulleted",
    labelKey: "modesTitle",
    view: "modes",
  },
  {
    icon: "mdi:content-copy",
    labelKey: "templates",
    view: "templates",
  },
  {
    icon: "mdi:heat-pump-outline",
    labelKey: "supplyControl",
    view: "supply-control",
  },
  {
    icon: "mdi:home-thermometer-outline",
    labelKey: "sensors",
    view: "sensors",
  },
  {
    icon: "mdi:home-heart",
    labelKey: "comfort",
    view: "comfort",
  },
  {
    icon: "mdi:clock-fast",
    labelKey: "preconditioning",
    view: "preconditioning",
  },
  {
    icon: "mdi:home-clock-outline",
    labelKey: "plannedReturn",
    view: "planned-return",
  },
  {
    icon: "mdi:stethoscope",
    labelKey: "diagnostics",
    view: "diagnostics",
  },
  {
    icon: "mdi:cog-outline",
    labelKey: "settings",
    view: "settings",
  },
];

export function panelTabIcon(view: VelairPanelView): string {
  return PANEL_TABS.find((tab) => tab.view === view)?.icon ?? "mdi:circle";
}
