import { configurationFingerprint, resolveDayLayout } from "../domain/day-layouts";
import { WEEKDAYS } from "../constants";
import type { VelairApiClient } from "../api/client";
import { draftBlocksFromScheduleBlocks } from "../domain/draft-blocks";
import { bindingsFromBlocks, linkedDraftBlocks } from "../domain/linked-schedules";
import type {
  BlockDraftSource,
  DraftScheduleBlock,
  ScheduleResponse,
  ScheduleTemplate,
  VelairCardConfig,
} from "../types";

type ScheduleStateHost = {
  _saving?: boolean;
  _draftSavedDayLayoutKey?: string;
  _draftDayLayoutKey?: string;
  _layoutOnlyDirty?: boolean;
  _dayLayoutConflict?: boolean;
  _groupBaseChosen?: boolean;
  _draftContentBaseline?: string;
  _normalizeDraftBlocks?(): import("../types").NormalizedBlocks;
  _draftTemplateLink?: import("../types").TemplateLink;
  _draftConfigurationRevision?: number;
  _config: VelairCardConfig;
  _copyTargets: Set<string>;
  _data?: ScheduleResponse;
  _dirty: boolean;
  _dirtyEntityId?: string;
  _draftBlocks: DraftScheduleBlock[];
  _error?: string;
  _hasExternalConfig: boolean;
  _loading: boolean;
  _saveMessage?: string;
  _selectedEntity?: string;
  _selectedTemplateKey: string;
  _selectedWeekday: string;
  _subscribing: boolean;
  _scheduleSubscriptionGeneration?: number;
  _templateDirty: boolean;
  _templateDraftBlocks: DraftScheduleBlock[];
  _templateDraftKey: string;
  _unsubscribeUpdates?: () => Promise<void> | void;
  _zoneTargets: Set<string>;
  _api(): VelairApiClient | undefined;
  _applyScheduleData(data: ScheduleResponse, options?: { forceDraft?: boolean }): void;
  _confirmDiscardChanges(): boolean;
  _loadSchedule(): Promise<void>;
  _initialScheduleWeekday(firstWeekday: string): string;
  _markDirty(): void;
  _orderedZoneIds(entityIds: string[]): string[];
  _visibleZoneIds(entityIds: string[]): string[];
  _resetDraftBlocks(): void;
  _resetTemplateDraft(template?: ScheduleTemplate): void;
  _scheduleTemplates(): ScheduleTemplate[];
  _syncPauseTick(): void;
  _t(key: string): string;
  _temperatureUnit(entityId?: string): string;
};

export function asScheduleStateHost(host: unknown): ScheduleStateHost {
  return host as ScheduleStateHost;
}

export async function loadSchedule(host: ScheduleStateHost): Promise<void> {
  const api = host._api();
  if (!api || host._loading) {
    return;
  }

  const generation = host._scheduleSubscriptionGeneration;
  const current = () => generation === host._scheduleSubscriptionGeneration;
  host._loading = true;
  host._error = undefined;
  try {
    const data = await api.getSchedule();
    if (current()) host._applyScheduleData(data);
  } catch (error) {
    if (current()) host._error = error instanceof Error ? error.message : host._t("unableLoad");
  } finally {
    if (current()) host._loading = false;
  }
}

export async function subscribeUpdates(host: ScheduleStateHost): Promise<void> {
  const api = host._api();
  if (!api || host._unsubscribeUpdates || host._subscribing) {
    return;
  }

  host._subscribing = true;
  try {
    host._unsubscribeUpdates = await api.subscribeUpdates((message: { loaded?: boolean; schedule?: ScheduleResponse }) => {
      if (!message.loaded || !message.schedule) {
        void host._loadSchedule();
        return;
      }

      host._applyScheduleData(message.schedule);
    });
  } catch (error) {
    host._error = error instanceof Error ? error.message : host._t("unableSubscribe");
  } finally {
    host._subscribing = false;
  }
}

export function applyScheduleData(
  host: ScheduleStateHost,
  data: ScheduleResponse,
  options: { forceDraft?: boolean } = {},
): void {
  const isInitialDataLoad = !host._data;
  if (host._dirty) {
    const savedKey = data.zones[host._selectedEntity ?? ""]?.day_layout_key;
    host._dayLayoutConflict = (savedKey ?? "individual") !== (host._draftSavedDayLayoutKey ?? "individual");
  }
  host._data = data;
  if (!host._hasExternalConfig) {
    host._config = {
      first_weekday: data.settings.first_weekday,
      zone_order: data.settings.zone_order,
    };
  }
  if (isInitialDataLoad) {
    host._selectedWeekday = host._initialScheduleWeekday(data.settings.first_weekday);
  }
  const zoneIds = host._orderedZoneIds(data.configured_entities);
  const visibleZoneIds = host._visibleZoneIds(data.configured_entities);
  if (!host._selectedEntity || !data.configured_entities.includes(host._selectedEntity)) {
    host._selectedEntity = zoneIds[0];
  }
  if (visibleZoneIds.length && host._selectedEntity && !visibleZoneIds.includes(host._selectedEntity)) {
    host._selectedEntity = visibleZoneIds[0];
  }
  if (host._selectedTemplateKey && !host._scheduleTemplates().some((template: { key: string }) => template.key === host._selectedTemplateKey)) {
    host._selectedTemplateKey = "";
  }
  const selectedTemplate = host._scheduleTemplates().find((template: { key: string }) => template.key === host._selectedTemplateKey);
  if (!selectedTemplate) {
    host._resetTemplateDraft();
  } else if (options.forceDraft || !host._templateDirty || host._templateDraftKey !== selectedTemplate.key) {
    host._resetTemplateDraft(selectedTemplate);
  }

  host._syncPauseTick();

  if (options.forceDraft || !host._dirty) {
    host._resetDraftBlocks();
  }
}

export function draftContentFingerprint(host: ScheduleStateHost): string {
  if (host._draftTemplateLink?.mode === "full") return configurationFingerprint(host._draftTemplateLink);
  const normalized = host._normalizeDraftBlocks?.();
  if (normalized?.ok) return configurationFingerprint(host._draftTemplateLink
    ? bindingsFromBlocks(host._draftTemplateLink, normalized.blocks)
    : normalized.blocks.map(({ slot_id: _slot, ...block }) => block));
  return configurationFingerprint({ blocks: host._draftBlocks, link: host._draftTemplateLink });
}

export function resetDraftBlocks(host: ScheduleStateHost): void {
  const zone = host._selectedEntity ? host._data?.zones[host._selectedEntity] : undefined;
  host._draftDayLayoutKey = resolveDayLayout(zone?.day_layout_key).layout.key;
  host._draftSavedDayLayoutKey = zone?.day_layout_key ?? "individual";
  host._dayLayoutConflict = false;
  host._layoutOnlyDirty = false;
  host._groupBaseChosen = false;
  const blocks = zone?.schedule?.[host._selectedWeekday] ?? [];
  host._draftTemplateLink = structuredClone(zone?.template_links?.[host._selectedWeekday]);
  host._draftConfigurationRevision = host._data?.configuration_revision;
  host._draftBlocks = host._draftTemplateLink ? linkedDraftBlocks(host._draftTemplateLink, host._data?.templates ?? [], host._temperatureUnit(host._selectedEntity)) : draftBlocksFromScheduleBlocks(
    blocks,
    host._temperatureUnit(host._selectedEntity),
  );
  host._draftContentBaseline = draftContentFingerprint(host);
  host._dirty = false;
  host._dirtyEntityId = undefined;
}

export function selectEntity(host: ScheduleStateHost, entityId: string): boolean {
  if (host._saving) return false;
  if (entityId === host._selectedEntity) return true;
  if (host._dirty && !host._confirmDiscardChanges()) return false;
  host._selectedEntity = entityId;
  host._saveMessage = undefined;
  host._copyTargets = new Set();
  host._zoneTargets = new Set();
  host._resetDraftBlocks();
  return true;
}

export function selectWeekday(host: ScheduleStateHost, weekday: string): boolean {
  if (host._saving) return false;
  if (!WEEKDAYS.includes(weekday)) {
    return false;
  }
  if (weekday === host._selectedWeekday) return true;
  if (host._dirty && !host._layoutOnlyDirty && !host._confirmDiscardChanges()) return false;
  const pendingLayout = host._dirty && host._layoutOnlyDirty ? {
    _draftDayLayoutKey: host._draftDayLayoutKey,
    _draftSavedDayLayoutKey: host._draftSavedDayLayoutKey,
    _draftConfigurationRevision: host._draftConfigurationRevision,
    _dayLayoutConflict: host._dayLayoutConflict,
  } : undefined;
  host._selectedWeekday = weekday;
  host._saveMessage = undefined;
  host._copyTargets = new Set();
  host._zoneTargets = new Set();
  host._resetDraftBlocks();
  if (pendingLayout) { Object.assign(host, pendingLayout); host._markDirty(); host._layoutOnlyDirty = true; }
  return true;
}

export function blocksForSource(host: ScheduleStateHost, source: BlockDraftSource): DraftScheduleBlock[] {
  return source === "template" ? host._templateDraftBlocks : host._draftBlocks;
}

export function setBlocksForSource(
  host: ScheduleStateHost,
  source: BlockDraftSource,
  blocks: DraftScheduleBlock[],
): void {
  if (source === "template") {
    host._templateDraftBlocks = blocks;
    return;
  }

  host._draftBlocks = blocks;
}

export function markBlocksDirty(host: ScheduleStateHost, source: BlockDraftSource): void {
  if (source === "template") {
    host._templateDirty = true;
    return;
  }

  host._markDirty();
}
