  protected updated(changedProperties: Map<string, unknown>): void {
    dismissDisconnectedInlineHelp();
    this._refreshPresetPreviews();
    if (changedProperties.has("presetKey")) this._presetKeyApplied = false;
    this._applyLearningDiagnosticEntity();
    if (changedProperties.has("resourceUsage")) this._resourceUsageApplied = false;
    if (this.presetKey && this._data && !this._presetKeyApplied) { this._presetKeyApplied = true; void this._editPreset(this.presetKey); }
    if (this.resourceUsage && this._data && !this._resourceUsageApplied) { this._resourceUsageApplied = true; void this._openResourceUsage(this.resourceUsage); }
    if (!this.scheduleSession && changedProperties.has("hass") && this.hass && !this._data && !this._loading) {
      void this._loadSchedule();
    }
    if (changedProperties.has("hass") && this.hass) {
      void this._subscribeUpdates();
    }
    if (changedProperties.has("_saveMessage") && !this._saveMessage) {
      this._clearSuccessNoticeTimer();
    }
    if (changedProperties.has("_data")) {
      const previous = changedProperties.get("_data") as ScheduleResponse | undefined;
      if (previous && previous.configuration_revision !== this._data?.configuration_revision && this._templateDirty && this._templateDraftBlocks.some((block) => block.preset_key)) queueTemplatePreview(asTemplateActionsHost(this));
      this._syncOperationStatusTimer();
    }
    if (changedProperties.has("_loading") || changedProperties.has("_data")) {
      this._syncInitialLoadingState();
    }
    if (
      this._effectiveView() === "templates" &&
      (changedProperties.has("view") ||
        changedProperties.has("_data") ||
        changedProperties.has("_selectedTemplateKey") ||
        changedProperties.has("_templateListCanScrollUp") ||
        changedProperties.has("_templateListCanScrollDown"))
    ) {
      window.requestAnimationFrame(() => this._syncTemplateListScrollIndicators());
    }
    if (changedProperties.has("view") || changedProperties.has("_data")) {
      this._syncTimelineNowTick();
    }
    if (changedProperties.has("view") || changedProperties.has("_config") || changedProperties.has("hass")) {
      void this._syncDiagnosticsSubscription();
    }
    this._syncDiagnosticsLogResizeObserver();
    this._syncClimateCardActionsResizeObserver();
    if (changedProperties.has("_sharedDemandDirty") || changedProperties.has("_plannedReturnDirty") || changedProperties.has("_dirty") || changedProperties.has("_profileScheduleDirty") || changedProperties.has("_presetLibraryDirty") || changedProperties.has("_templateDirty") || changedProperties.has("_templateApplication")) {
      this.dispatchEvent(new CustomEvent("velair-dirty-changed", {
        bubbles: true,
        composed: true,
        detail: {
          dirty: this._sharedDemandDirty || this._plannedReturnDirty || Boolean(this._templateApplication?.dirty) || this._templateDirty || this._presetLibraryDirty || (this._scheduleSource === "profile" ? this._profileScheduleDirty : this._dirty),
          scope: this._scheduleSource === "profile" ? "profile" : "default-schedule",
        },
      }));
    }
    const effectiveView = this._effectiveView();
    const showsOverviewTimeline = effectiveView === "overview"
      || effectiveView === "overview-timeline"
      || effectiveView === "climate";
    if (!showsOverviewTimeline) {
      this._overviewTimelineScrollInitialized = false;
    } else if (this._data && !this._overviewTimelineScrollInitialized) {
      this._overviewTimelineScrollInitialized = true;
      window.requestAnimationFrame(() => this._scrollOverviewTimelineToNow());
    }
    if (this._climateCardActionsMenuOpen && (
      !this.renderRoot.querySelector(".climate-card-actions-menu-trigger")
      || !this.renderRoot.querySelector(".climate-card-actions-menu")
    )) {
      this._closeClimateCardActionsMenu();
    }
  }

